/**
 * 题库搜索器 - 模拟 qqsgtk.cn 搜索逻辑
 * 1. 纯拼音 → idx 字段匹配
 * 2. 中文 → 去除标点后逐字匹配（不要求连续子串）
 */
var QuestionSearcher = (function() {

  // 规范化：全角转半角后，只保留中文/字母/数字，其余标点符号一律去掉
  // 白名单方式比黑名单更彻底，可排除 OCR 输出的任意标点（破折号、省略号、间隔号等）
  function normalize(s) {
    return s
      .replace(/[\uFF01-\uFF5E]/g, function(m) {
        return String.fromCharCode(m.charCodeAt(0) - 0xFEE0);
      })
      .replace(/[^\u4e00-\u9fa5a-zA-Z0-9]+/g, '')
      .toLowerCase();
  }

  // 判断 s 中每个字符是否按顺序出现在 target 中
  function charMatch(s, target) {
    var si = 0, ti = 0;
    while (si < s.length && ti < target.length) {
      if (s.charAt(si) === target.charAt(ti)) si++;
      ti++;
    }
    return si === s.length;
  }

  function QuestionSearcher(bank) {
    this.bank = bank || [];
    // 预计算规范化字段，避免每次搜索都重复 normalize（约 6900 题 × 2 个字段）
    this._normBank = [];
    for (var i = 0; i < this.bank.length; i++) {
      var item = this.bank[i];
      this._normBank.push({
        q: item.q,
        a: item.a,
        idx: item.idx,
        nq: normalize(item.q),
        na: normalize(item.a)
      });
    }
  }

  QuestionSearcher.prototype.search = function(query) {
    if (!query || !query.trim()) return [];
    
    query = query.trim();
    var isPinyin = /^[a-zA-Z]+$/.test(query);
    var lowerQuery = query.toLowerCase();
    var normQuery = isPinyin ? null : normalize(query);
    var results = [];
    
    for (var i = 0; i < this._normBank.length; i++) {
      var item = this._normBank[i];
      var hit = false;
      
      if (isPinyin) {
        hit = item.idx && item.idx.indexOf(lowerQuery) !== -1;
      } else {
        // 中文：规范化后逐字匹配（使用预计算字段）
        hit = charMatch(normQuery, item.nq) || charMatch(normQuery, item.na);
      }
      
      if (hit) {
        results.push({q: item.q, a: item.a});
        if (results.length >= 20) break;
      }
    }
    
    if (results.length === 0 && !isPinyin) {
      var mixedPinyin = '';
      for (var c = 0; c < query.length; c++) {
        var ch = query.charAt(c);
        if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')) {
          mixedPinyin += ch.toLowerCase();
        }
      }
      if (mixedPinyin) {
        for (var j = 0; j < this._normBank.length; j++) {
          var item2 = this._normBank[j];
          if (item2.idx && item2.idx.indexOf(mixedPinyin) !== -1) {
            results.push({q: item2.q, a: item2.a});
            if (results.length >= 20) break;
          }
        }
      }
    }
    
    return results;
  };

  return QuestionSearcher;
})();